WordHunterWoW_QuestEN[99046] = { title = "The Lost Runner", description = "The Council of the Forest sent a small group of sentinels to the Oracle Tree some time ago. The tree sends messages to our elders, and it falls to us to deliver them to Darnassus safely.\n\nI received word that our most recent runner has not yet arrived. The Oracle's messages vary in frequency, but it has been abnormally long.\n\nPlease head towards the Oracle Glade along the road to the west and check on her. It would have been Eralya Leafshadow's turn, and she is still in training. Elune guide you.", objectives = "Search for Sentinel Eralya Leafshadow on the road leading to the Oracle Glade.", completion = "Elune's grace... I shall not die... alone..." }
WordHunterWoW_QuestEN[99047] = { title = "Not Dead Yet", description = "My sisters and I... were dispatched... Oracle Tree...\n\nTree... message. I... harpies... everywhere...\n\n<Eralya coughs up blood, grimacing through the pain.>\n\nI may not have long... no one coming. Please... Byancie... in Dolanaar...", objectives = "Seek aid from Byancie in Dolanaar for Sentinel Eralya Leafshadow.", completion = "The harpies have become afflicted by the same foulness showing up throughout the forest. I'm sure that is what ails Sentinel Eralya as well.\n\nWe must hurry. It won't be long before she succumbs to her injuries." }
WordHunterWoW_QuestEN[99048] = { title = "A Missing Hand", description = "A member of the Shattered Hand, a group of more... subtle fighters, was watching Tiragarde Keep from a distance. Her reports suddenly stopped coming in.\n\nI doubt the humans would have caught her, so I'm concerned something more dangerous is at play. See if you can find her. Hopefully the messages are just delayed.", objectives = "Find Heglan Shadeeye north of Tiragarde Keep.", completion = "Heglan's body lies cold within the wreckage of the hut.\n\nWhatever killed her doesn't seem to be human. There may be signs of what happened nearby." }
WordHunterWoW_QuestEN[99049] = { title = "Threat from Below", description = "The nearby area is destroyed with obvious signs of a skirmish. Whatever ambushed Heglan didn't make it out unscathed. There's probably signs nearby of what happened.\n\nOrgnil will probably want to see any evidence left by the attackers.", objectives = "Find signs of what attacked Heglan Shadeeye.", progress = "Did you find her?", completion = "This banner and blade piece belong to the naga! They must have come down the coast from the north.\n\nWe cannot let them establish a foothold here. The pressure from both directions would be too much for Razor Hill." }
WordHunterWoW_QuestEN[99050] = { title = "The Great Tree Provides", description = "I will need your help acquiring the ingredients I need to stop the affliction long enough for Eralya to make it back here for further treatment.\n\nThankfully, our living home is still bountiful and will provide in our time of need.\n\nThe core ingredient is dewy lasher fronds. You'll find them around Lake Al'Ameth directly south of here, or Wellspring Lake and its river to the northwest.\n\nIn addition, I'll need an empty vial and some spring water. Both can be bought here in town, or traded for.", objectives = "Collect 6 Dewy Lasher Fronds, an Empty Vial, and a Refreshing Spring Water for Byancie in Dolanaar.", completion = "Thank you for your help. Please, accept this to help with the costs of the vial and water.\n\nNow, to make the salve. It should only take a moment." }
WordHunterWoW_QuestEN[99051] = { title = "Threat from Below", description = "It wouldn't be the first time those snakes bothered us. They need to be taught that their presence is not tolerated here.\n\nFind where their scouts are setting up camp and slaughter them. Bring me back their fins as proof. We need to act fast to make sure they understand.", objectives = "Collect 9 Naga Spinefins.", progress = "Hopefully those snake scum aren't giving you trouble?", completion = "Hopefully that sends them packing back to the north. I'll have some grunts keep an eye out for any stragglers or funny business." }
WordHunterWoW_QuestEN[99052] = { title = "Threat from Below", description = "One of my scouts has reported a sea giant followed those naga down here. Not sure if they brought him intentionally or what, but he's dangerous in any case.\n\nIt's a young one, but it could still rip an orc in half in a heartbeat if they were caught off guard. I need him gone. But I'd suggest you find some help to deal with it.", objectives = "Kill the sea giant along Durotar's north coast and bring back proof of your accomplishment.", progress = "Give 'em blood and thunder!", completion = "Ha! I could hear his body fall from here!\n\nBe proud of your kill today; not many can claim they survived a fight with a sea giant." }
WordHunterWoW_QuestEN[99053] = { title = "Escaping Ban'ethil", description = "My prayers have been answered! I am thankful that you have fought your way down here.\n\nI was sent here by the Oracle Tree to deliver a message to the slumbering druids here only to find it completely overrun by furbolg! They ambushed me before I could turn back and brought me down here--I fear for their next meal.\n\nI don't know about you, but I loathe this place. Under the earth is no place for the kaldorei.", objectives = "Help Sentinel Lynessa Duskblossom escape Ban'ethil Barrow Den, and report her safety to Sentinel Kyra Starsong in Dolanaar.", completion = "Thank Elune you were around to help Lynessa avoid a dark fate with the Gnarlpine. She's one of our best, and a personal friend.\n\nPlease, take this in thanks. May it serve you well in keeping the kaldorei safe." }
WordHunterWoW_QuestEN[99073] = { title = "Easing Suffering", description = "The salve is ready. Take it to Eralya swiftly.\n\nI do not know if it will truly cure her. The rot festers quickly, and grows in strength as it spreads.\n\nIt will, if nothing else, ease her suffering. And that is still worth your haste.", objectives = "Take the Lashwater Salve to Sentinel Eralya Leafshadow on the road to the Oracle Tree.", completion = "<Eralya's breath calms quickly as you help her ingest the salve. She may not survive, but is at relative peace.>" }
WordHunterWoW_QuestEN[99079] = { title = "Longwalker Malah", description = "The Longwalkers are our people's most trusted scouts. Though their loyalty lies with the High Chieftain alone, young Baine at times seeks their aid.\n\nThis is one such time. Longwalker Malah was dispatched near our borders to the east and did not return last night after three days. When this occurs, it is our duty to confirm their safety.\n\nI must ensure the village remains safe. Prove yourself, and seek Malah out. You will know her by her headband and feathered staff, emblematic of the Longwalkers.", objectives = "Find Longwalker Malah Longwind east of Bloodhoof Village, near the edge of Mulgore.", completion = "It is clear that Malah did not die naturally. Arrows cover her back and the ground nearby." }
WordHunterWoW_QuestEN[99080] = { title = "Drive Them Out", description = "Hear my words well: we will not yield a single blade of grass to the centaur.\n\nGo to their camp now, before they have rested and have a chance to ride to our village. Slaughter them all. Ensure none escape to the Barrens to rally others to their aid.\n\nIf you find the leader of this would-be raiding party, bring me his head so that it may serve as a warning to others who dare tread on our ancestral homeland.", objectives = "Kill 6 Galak Centaurs, 4 Galak Outrunners, and bring the head of Herak the Pillager to Baine Bloodhoof.", completion = "You are covered in centaur blood. Remember this feeling. It is an honor unlike any other among our people.\n\nI could hear the moment the last fell, and their thunderous stampede echoed no longer. Well done!\n\nToday marks a great victory for our village, and a security our young ones need now more than ever. You have my deepest thanks, young {class}." }
WordHunterWoW_QuestEN[99081] = { title = "Grim Tidings", description = "You can see what appears to be a new centaur camp in the direction the arrows in Malah's back would have come from. There is a stir of activity, suggesting a small raiding party has made its way into Mulgore.\n\nThe Longwalker has a report in her still-clenched hand. Brave Wildrunner will want to know of Malah's fate--and her killers.", objectives = "Bring Longwalker Malah's Report to Brave Wildrunner in Bloodhoof Village.", completion = "This is most dire news indeed. We must inform Baine at once!" }
WordHunterWoW_QuestEN[99082] = { title = "The High Chieftain", description = "Your bravery defending your people demands recognition. Journey to Thunder Bluff to the northwest, our mighty city whose shadow grants us shade in the warmer months, and seek audience with my father.\n\nIt was he who led the charge with the young Warchief Thrall to reclaim these plains and drive the centaur away for good. As High Chieftain, he will reward you generously for your part in ensuring his own bravery is honored.\n\nYou must take a lift to reach the High Chieftain, who sits on the central rise.", objectives = "Seek audience with High Chieftain Cairne Bloodhoof in Thunder Bluff.", completion = "The Galak centaur dare show themselves in Mulgore?!\n\nYou have brought pride to your ancestors by driving them out. Perhaps that will remind them of the pain that awaits them should they do so again!\n\nPlease accept this gift in honor of this. May it serve you well as you venture out into the Earth Mother's kingdom, to the far reaches of this world." }
WordHunterWoW_QuestEN[99101] = { title = "Our Ancient Enemy", description = "Baine Bloodhoof leads our village. He must know of this incursion at once.\n\nBring him Longwalker Malah's report. You will find him at the center of town.\n\nQuickly, now. There is no time to waste!", objectives = "Bring Longwalker Malah's Report to Baine Bloodhoof.", completion = "<Baine reads the report, his gaze darkening.>\n\nThis will not stand. Thank you for delivering it to me, Vanyel." }
WordHunterWoW_QuestEN[99108] = { title = "Sparring Match", description = "Hail, young {class}. Though you are not a warrior and I cannot teach you that path, that does not mean you would not benefit from my tutelage.\n\nBefore you lies the arena. In it, it matters not who you call mother or whether you wield sword or bow. All are equal, and all learn to sharpen their horns in direct combat.\n\nWill you enter our space, and learn our ways for yourself? You may face any of these novices, or any other willing adversary. I care not which.", objectives = "Defeat 3 other players in duels or Novice Warriors for Tang Stonehoof.", completion = "You honor me with your abilities, {class}. Perhaps the new generation has hope yet.\n\nTake these to tend to your wounds, for many more battles await you in this harsh world." }
WordHunterWoW_QuestEN[99123] = { title = "Lost in the Shadows", description = "I decided to do a bit of scouting in the crag on my own. Unfortunately my magic ran out at the wrong time and I've been stuck hiding here since.\n\nIf you could help me escape, I would appreciate it.", objectives = "Help Pal'juh escape Kolkar Crag and bring news of your success to Master Vornal in Sen'jin Village.", completion = "Ah, Pal'juh got herself in trouble again, did she?\n\nHopefully she learns her lesson about going alone this time. Thank you for helping her. She's a promising {class}, just tends to act more like a raptor than a tiger." }
WordHunterWoW_QuestEN[99127] = { title = "A Net Disaster", description = "The fish just ain't biting today, and there's something wrong going on with them. It's not just empty hooks. I haven't seen a single minnow up in the water at all.\n\nLee here set up some traps overnight. Go check to see if we've at least got some stock there. If you find anything weird, make sure to show me.", objectives = "Check the fishing traps in Crystal Lake.", completion = "All the traps are like this? Seems our new neighboring nuisances are causing more destruction than we were aware of. I'll go broke if we don't do something about it." }
WordHunterWoW_QuestEN[99128] = { title = "Slimy Menace", description = "This can only be the work of those murlocs on the other side of the lake. They're disgusting little things, with a vicious temper and teeth to match. \n\nIf we let this continue, there won't be any fish to speak of anywhere in this lake. If you could clear them out a bit, it would help me a ton.", objectives = "Kill 4 Murlocs and 7 Murloc Streamrunner at Crystal Lake, then return to Jason Mathers.", completion = "I can hear their warbling from here, it'll be in my nightmares. Well, that should slow them down--although I have no doubt that they'll make up those numbers quickly." }
WordHunterWoW_QuestEN[99129] = { title = "A Man About a Murloc", description = "Remy mentioned murlocs the other day... I'm pretty sure he hates the little buggers as much as I do. \n\nHe might have some ideas on how to keep them away from my fish in the future. I'd like to ask you to go chat with him and see if there's anything he can think of.", objectives = "Speak with Remy \"Two Times\" about Jason's murloc problems.", completion = "I've been warning the guards about the murlocs. They won't listen.\n\nI have a few ideas on how to get back at those critters. I'll need your help getting what I need for it though." }
WordHunterWoW_QuestEN[99130] = { title = "An Enticing Offer", description = "I've got a few ideas on how to deal with murlocs. And one of those also helps some others in the process.\n\nThere's a weed often found on farms in the area called duskweed, and in large quantities the petals are toxic to most animals. If we make some murloc bait with the plant, hopefully that can train those creatures to stay away.\n\nAnd some farmers get their fields cleared in the process. Truly a win-win... truly a win-win.", objectives = "Collect 18 Vials of Animal Blood and 6 Duskweed Petals for murloc bait, then return to Remy \"Two Times\" in Goldshire.", completion = "Give me just a minute...\n\nIt's pretty simple bait, but as long as nobody's pet gets into it, it should be safe. Just tell Jason not to eat any of it." }
WordHunterWoW_QuestEN[99131] = { title = "Baited for Success", description = "Tell Mathers he can come pick up the bait later today. I'll give him the rundown on the proper usage.\n\nHopefully he'll be able to sell his fish again soon. And we'll have less murlocs in this world.", objectives = "Return to Jason Mathers.", completion = "Poisoned bait? As long as the fish aren't going to eat it, that should work. I'll visit Remy later to pick it up." }
WordHunterWoW_QuestEN[99134] = { title = "Discipline", description = "You are not a member of the Deathguard, and therefore have yet to disappoint me.\n\nAs a reward for your relative lack of incompetence, you shall punish those that have demonstrated such talents in excess.\n\nSwiftly now--{name}, is it?--or I shall add your name to my ledger for someone else's reward.", objectives = "Punish 5 Deathguards for Executor Zygand.", completion = "There are precious few delights afforded to us in death. Thankfully, pain is chief among them.\n\nYou please me this day, and therefore you please the Dark Lady. Perhaps you can be of further use." }
WordHunterWoW_QuestEN[99141] = { title = "Patience", description = "Make no mistake, {class}--the Dark Lady demands the perfect execution of her will. As an Executor, it is my duty to see that this happens.\n\nReports from several of my Deathguards are overdue. Needless to say, my patience has run out. Obtain their reports and bring them to me in the Dark Lady's name.\n\nYou will find Deathguard Dillinger just west of here, by the graveyard. Deathguard Kristof is stationed at the waystation to the east. And check on the abomination Gordo; he wanders west near Stillwater Pond.", objectives = "Obtain reports from Deathguard Dillinger, Deathguard Kristof, and Gordo for Executor Zygand.", progress = "You'd best have those reports in hand, or get out of my face.", completion = "I should have known better than to think an abomination could write anything of use. Let us keep that lapse of judgment between us.\n\nYou have pleased me, and therefore pleased the Dark Lady. Perhaps there is hope for you." }
WordHunterWoW_QuestEN[99142] = { title = "Tomb Weed", description = "If you're heading east, towards the Balnir Farmstead, I have more you might do for me. Good help is ever so hard to find these days, as your run-in with Gordo illuminates ever so clearly.\n\nAs I acquire doom weed I perform some minor alchemical alterations and replant them on that farmstead to cultivate my ultimate creation. I call it tomb weed, and it shall be the herald of my glorious destiny.\n\nDo keep an eye on the Scourge in the area while you're there. They seem... drawn... to the weed. Curious.", objectives = "Collect 5 Tomb Weed and deliver them back to Junior Apothecary Holland.", progress = "More interruptions! Wait, it's you. Were you able to recover the tomb weed?", completion = "Most glorious indeed!\n\n<Junior Apothecary Holland inspects the weeds.>\n\nHmm, I had hoped they would have matured a bit more violently. Nevertheless, progress is progress!\n\nA great many will die as a result of your actions this day. You should be proud." }
WordHunterWoW_QuestEN[99143] = { title = "Bottles and Baubles", description = "Those fish men must think like actual fish, right? Which means anything they like, fish will like!\n\nIf you rummage through some of their junk and return to me with anything that seems like it would make good bait, I'll reward you.", objectives = "Collect 6 pieces of shiny junk from the nearby Murloc camp.", completion = "An interesting collection. These should work well enough!\n\nHere's some of my own older supplies. It should help anyone trying to get their footing in fishing." }
WordHunterWoW_QuestEN[99144] = { title = "Seeking Refuge", description = "Light bless you for finding me. I was on my way from Bandarion Keep to deliver a message to Shari Stilwell in Brill when these monsters captured me. They wield the Light with a hatred in their hearts that makes what's left of my blood seethe. It goes against all I meditate for... all I strive to protect!\n\n<Bareth Dawnstone steadies himself.>\n\nI know some still take issue with my kind, but I assure you our intentions are pure. If you would aid me in escaping this place, I would be forever grateful.", objectives = "Help Bareth Dawnstone escape Crusader's Outpost, and report his safety to Shari Stilwell in Brill.", completion = "Blessings upon you for aiding Dawnstone. Our order is still taking root here and it would be devastating to lose one so promising before his time.\n\nPlease accept this as a token of our thanks. Should you ever take an interest in our ways, our monastery Bandarion Keep lies on the bluffs northwest of the Solliden Farmstead. We welcome all who seek guidance in the Light." }
WordHunterWoW_QuestEN[99145] = { title = "A Winter Veil Gift", description = "", objectives = "" }
WordHunterWoW_QuestEN[99152] = { title = "As Above, So Below", description = "While the Tarnished in Shadowvale to the southwest are definitely a problem, we cannot allow the cellars below the town to fester into a full-blown Scourge uprising on Bandarion Keep.\n\nI need to get these trainees up to snuff in case that happens. You, however, are going to receive what I like to call a crash course.\n\nTravel beneath Shadowvale and retrieve some of their wretched bones so we can study them further. I need ones that still retain some of the initial reanimation magic--that's glowing ones.", objectives = "Collect 6 Faintly Glowing Bones for Hilda the Breaker.", progress = "You'd best not be returning empty-handed. I either need the bones I asked for, or your body on a stretcher to confirm you at least gave it your all trying to get them.", completion = "Well done, {class}. With these bones we may be able to better understand how such a threat was able to go unnoticed for so long." }
WordHunterWoW_QuestEN[99153] = { title = "The One That Got Away", description = "Oi, you! Word travels quickly among our ranks. I heard about the work you did with the cultists around the remnants of the battle with Naxxramas.\n\nProblem is, one of them cultists got away with a piece of the focusing crystal. Seems to still have some juice in it. Best guess we have is it's somewhere beneath Shadowvale. It's either raising 'em or making 'em stronger, and you don't want either one.\n\nFind that crystal before this gets out of hand.", objectives = "Find the Hidden Crystal Fragment beneath Shadowvale for Ephram Barbaro.", progress = "Did you find the damned thing?", completion = "Well done--and quick, too! Now onto my favorite part..." }
WordHunterWoW_QuestEN[99156] = { title = "Rear Guard Patrol", description = "Damn it all! A new report came in while you were on patrol. There has been a sighting of a rogue abomination wandering Eastern Tirisfal Glades, near Venomweb Vale.\n\nSomething is wrong. Abominations don't just slip through the Bulwark unnoticed.\n\nKeep this matter on a strictly need-to-know basis. That said, such a creature will not fall easily; you will need allies if you wish to be more than its next meal.\n\nSee this through, and you will be duly rewarded. Bring me its heart as proof of the deed.", objectives = "Bring Riptear's Heart to Deathguard Linnea.", progress = "Have you dealt with our little problem?", completion = "You are a testament to the cunning and coordination that all Forsaken possess--something the mindless Scourge will never have.\n\nPlease accept this as thanks for your efforts, as promised." }
WordHunterWoW_QuestEN[99158] = { title = "Dawn in the Mountains", description = "There's a priest out in the mountains that belongs to an organization called the Argent Dawn. They're a holy group that is dedicated to finding and destroying the unholy and unnatural.\n\nFather Gavin though, he's mostly the type that seeks to help and heal everyone rather than grab a weapon. He's fixed up an old building to serve as a rest spot for travelers and called it Misty Pine Refuge. I've got a shipment of holy candles that I need to get him. Could you bring them to him if you're going that way?", objectives = "Bring the crate of candles to Father Gavin at Misty Pine Refuge.", completion = "Ah. Candles from Ironforge.\n\nWhile I am mostly able to live independently in my hermitage, there are a few key things that I appreciate from the city and the pious." }
WordHunterWoW_QuestEN[99159] = { title = "Finding Warmth", description = "My hearth is open to warm any soul, but I'd like to ask you to help me if you could.\n\nI simply need more firewood. It is something I would normally do myself, but I have been preoccupied by other tasks.", objectives = "Collect 14 pieces of firewood.", completion = "Ah, perfect. These will do--any that are too wet to use right now I will leave to dry.\n\nNow, if you're willing, I have more tasks I could use help with." }
WordHunterWoW_QuestEN[99160] = { title = "Rime's Wrath", description = "You may have noticed the elementals nearby. A shelf of rock and ice fell from the mountain peaks a few days ago and riled them up.\n\nThese frozen mountains are already treacherous for the average dwarf or human without the elements taking form. I am not one for fighting anymore--so any of the spirits you can kill would help make the road safer.", objectives = "Destroy 10 minor ice elementals.", completion = "I wish we could have simply placated them. Unfortunately it was beyond my knowledge and they were too dangerous to leave unchecked." }
WordHunterWoW_QuestEN[99161] = { title = "Rime's Wrath", description = "I noticed that the first elemental that appeared after the rockslide was larger than its peers. And from what I can tell, it has been the source of occasional weather changes and other minor slides.\n\nI've been calling it 'Avala', if you could kill it and retrieve the core as proof, I will reward you.", objectives = "Kill Avala and retrieve its core.", completion = "Light bless you, {class}. Your efforts make this area much safer and hopefully will prevent unnecessary deaths." }
WordHunterWoW_QuestEN[99162] = { title = "Treacherous Cold", description = "Even mountaineers from Ironforge have to keep their wits about them when traversing through the peaks of Dun Morogh. Falling snow and ice often spells the end of some more novice members' lives.\n\nAfter a slide, I usually try to find any sign of survivors or victims--while praying to the Light that there's nothing to be found. But with the elements acting up, I've held off wandering too far. If you could look for some lost mountaineers and bring me their rifles, I will return them to Ironforge.", objectives = "Collect the rifles of fallen mountaineers.", completion = "The mountaineers engrave their names on the stock of their rifles. It helps identify them should something happen. I'll send these back to Ironforge--there someone will pass them on to any family." }
WordHunterWoW_QuestEN[99187] = { title = "The Reliquary of Tyr", description = "You may not be a Knight of Lordaeron--though perhaps you are, in a way. However, a Paladin you remain... and you know the power of an oath.\n\nThe Blackmaw are powerful totemics, and they would recognize the power of such an artifact as the Reliquary. Undoubtedly, they still possess it.\n\nThusly I'd ask this of you now--finish the quest I started. Return the Reliquary of Tyr here to Tirisfal Glades where it belongs. Only then will my oath be discharged, and my spirit may move on from this world.", objectives = "Travel to Blackmaw Hold in Kalimdor, and recover the Reliquary of Tyr." }
WordHunterWoW_QuestEN[99191] = { title = "A Donation of Wool", description = "The High Order are currently accepting donations for wool cloth.\n\nA donation of sixty pieces of wool cloth will net you full recognition by the High Order for your generous actions.  Sixty pieces of wool should prove to be a sufficient amount for the High Order's needs for now.\n\nIf you have the sixty pieces of wool cloth on you and are ready to donate them, I'm able to take them from you now.", objectives = "" }
WordHunterWoW_QuestEN[99192] = { title = "A Donation of Silk", description = "", objectives = "" }
WordHunterWoW_QuestEN[99193] = { title = "A Donation of Mageweave", description = "", objectives = "" }
WordHunterWoW_QuestEN[99194] = { title = "A Donation of Runecloth", description = "", objectives = "" }
WordHunterWoW_QuestEN[99196] = { title = "A Donation of Wool", description = "The Windshapers are currently accepting donations for wool cloth.\n\nA donation of sixty pieces of wool cloth will net you full recognition by the Windshapers for your generosity.\n\nIf you have the sixty pieces of wool cloth on you and are ready to donate them, I'm able to take them from you now.", objectives = "", progress = "The Windshapers are currently accepting donations for wool cloth.\n\nA donation of sixty pieces of wool cloth will net you full recognition by the Windshapers for your generosity. \n\nIf you have the sixty pieces of wool cloth on you and are ready to donate them, I'm able to take them from you now." }
