WordHunterWoW_QuestEN[99199] = { title = "A Donation of Runecloth", description = "", objectives = "" }
WordHunterWoW_QuestEN[99201] = { title = "Swift as the Wind", description = "Ey, welcome back {class}! \n\nZjolnir will provide ya with a free armored mount once you have trained journeyman riding with me, and after that ya be able to purchase any additional armored mounts.\n\nSpeak to me when ya have enough gold, and I will teach ya to master raptor riding.", objectives = "Learn the Journeyman Riding skill from Xar'ti." }
WordHunterWoW_QuestEN[99202] = { title = "Swift as the Wind", description = "Greeting once more, {class}. The time has come for you learn to ride one of our grandest mounts--the armored kodo.\n\nHarb will provide you with a free mount once ye have completed your training with me, and after you will be able to purchase any additional mounts you would like, just as before.\n\nThis will be expensive, but speak to me when you have enough coin. I will finish your training.", objectives = "Learn the Journeyman Riding skill from Kar Stormsinger." }
WordHunterWoW_QuestEN[99203] = { title = "Swift as the Wind", description = "Ah, you've returned. Very good. Are you ready to learn to ride an armored galestrider?\n\nAs before, if you take the next step in your training with me, I will provide you with a free mount, and after you will be able to purchase any additional mounts you would like. \n\nIt won't be cheap, but speak to me when you have enough coin. I will teach you about riding armored galestriders.", objectives = "Learn the Journeyman Riding skill from Genn Fairweather." }
WordHunterWoW_QuestEN[99204] = { title = "Swift as the Wind", description = "You have returned. Good. It's time to take your next steps. \n\nOgunaro will provide you with a free mount once you have completed your final leg of training with me, and after you will be able to purchase any additional mounts you would like, as before.\n\nSpeak to me when you have enough gold, and I will finish your training.", objectives = "Learn the Journeyman Riding skill from Kildar." }
WordHunterWoW_QuestEN[99205] = { title = "Swift as the Wind", description = "You've returned, {name}. Very good. It's time to learn to ride a proper mount, your armored sabercat.\n\nLelanai will provide you with a free mount once ye have trained with me, and after you will be able to purchase any additional mounts ye would like. There are many creatures out in the world, and each requires their own riding skill, but you will have to find trainers for each.\n\nSpeak to me when you have enough coin, and I will teach you all I know about riding sabers.", objectives = "Learn the Journeyman Riding skill from Jartsam." }
WordHunterWoW_QuestEN[99206] = { title = "Swift as the Wind", description = "I'm glad you made your way back to me. I can tell by the scratches on your skin and the dirt on your armor that you've seen much of the world. It's time we got you a proper steed.\n\nKatie will provide you with a free mount once ye have completed the final leg of your training with me, and after you will be able to purchase any additional mounts you would like just as before.\n\nSpeak to me when you have enough coin, and I will teach you all I know about riding armored horses.", objectives = "Learn the Journeyman Riding skill from Randal Hunter." }
WordHunterWoW_QuestEN[99207] = { title = "Swift as the Wind", description = "I can tell that you've come far enough to handle one of our top of the line, most powerful swift mechanostriders.\n\nMilli will provide you with a free mount once you have completed your final round of training with me, and after you will be able to purchase any additional mounts you would like just as before.\n\nThis won't be cheap, but speak to me when you have enough gold. I will teach you about riding our supercharged mechanostriders!", objectives = "Learn the Journeyman Riding skill from Binjy Featherwhistle." }
WordHunterWoW_QuestEN[99208] = { title = "Swift as the Wind", description = "You are back. Good. It's time for you to learn to master the steed of a true Forsaken--the skeletal warhorse.\n\nZachariah will provide you with a free mount once you have completed the final round of your training with me, and after you will be able to purchase any additional mounts you desire.\n\nSpeak to me when you have enough coin, and I will teach you about skeletal warhorses.", objectives = "Learn the Journeyman Riding skill from Velma Warnam." }
WordHunterWoW_QuestEN[99213] = { title = "An Epic Ride", description = "Greetings, {name}! I am so glad to see you've returned to us.\n\nIt would seem you have enough experience to ride our fastest and fiercest steeds. You won't find a more steadfast companion for your journeys.\n\nChoosing one may be difficult as they are all excellent and trained to be steady even when in danger. Some may even recognize you from the last time you were here.\n\nGo and examine the armored horses and return to me when you have made your choice.", objectives = "Inspect the armored riding horses to choose your epic mount." }
WordHunterWoW_QuestEN[99214] = { title = "An Epic Ride", description = "Greetings, friend! I am pleased to see you again. Today you have enough experience and aptitude to bond with our fastest and fiercest sabers.\n\nThese sabers are, of course, extremely intelligent and fiercely loyal to their bonded rider. You won't find a more noble and steadfast companion.\n\nAs such, you have an important choice to make. You and your saber will traverse the world together, so choose wisely!\n\nGo, examine the armored sabers and return to me when you have made your choice.", objectives = "Inspect the armored riding sabers to choose your epic mount." }
WordHunterWoW_QuestEN[99233] = { title = "Brawl at the Maul", description = "There must be more to the Maul than this!\n\nPerhaps the loud Spectator who oversees the event at Dire Maul will know!", objectives = "Speak with Griniblix the Spectator above the Maul in Dire Maul." }
WordHunterWoW_QuestEN[99257] = { title = "A Heart of Crystal", description = "While I watched in horror as you frolicked through the haunted woods with my precious relic, your meddling did inspire an idea.\n\nThe unstable rifts you encountered are the precursors to our pylon guards. We have been unable to conjure more for centuries, and I worry what might happen when those that remain inevitably flicker out.\n\nI know it seems counterintuitive, but see if you can find another pylon protector nearly on the verge of collapse and recover their Crystal Heart. I'll explain more after.", objectives = "Slay a Decrepit Pylon Protector for their Depleted Crystal Heart and bring it to Historian Biraxas within the temple of Shen'dralas." }
WordHunterWoW_QuestEN[99258] = { title = "Mana Mania", description = "While sourcing the gems necessary to conjure the elementals is a challenge itself, the bigger concern is whether there is still enough loose mana in Shen'dralas to create them. With this heart, we can confirm once and for all whether we need to begin researching other means of defense.\n\nFor you, the task is simple. Simply toss this gem into one of those unstable rifts. If we're lucky, you'll have a fight on your hands. Don't feel compelled to hold back, if it works once, it will work again.", objectives = "Throw the Depleted Crystal Heart into an Unstable Mana Rift. Return to Historian Biraxas within the temple of Shen'dralas with proof of success or failure." }
WordHunterWoW_QuestEN[99260] = { title = "Fillion's Mission", description = "I was tasked to retrieve important data on the flow of elemental energy from the Overlook Standing Stones. That data is vital to our plans to safely travel between Skywall and Azeroth. Without that data to aid in our calculations, our attempts to steer our skycutter ships through the elemental plane will fail.\n\nThe data is likely lost at this point, and I'm in no state to attempt to gather it again. I told the Supreme Magister of your role in saving me, and he wishes to speak with you again.", objectives = "Speak with Elaadrin Evengale in Valanaar.", completion = "Thank you for saving Fillion, {name}. I'm sure he told you how vital the data he was sent to retrieve is.\n\nWithout that data, our prospects for opening safe lanes of travel to Azeroth are in serious jeopardy. Our spies tell us that the Windshapers have themselves procured the means to traverse the planes, and no doubt wish to jealously guard this secret.\n\nAs ever, their own dogmatic hubris takes precedence over the good of our people. They are little better than the Al'Aketh." }
WordHunterWoW_QuestEN[99267] = { title = "An Unfortunate End", description = "", objectives = "" }
WordHunterWoW_QuestEN[99326] = { title = "Your First Horse", description = "Greetings! Are you here to examine our horses?\n\nThese steeds are descendants from both the historical Lordaeron stock and our own local horses. You won't find a more steadfast companion for your journeys.\n\nChoosing one may be difficult as they are all excellent and trained to be steady even when in danger. Don't forget, you and your horse will traverse the world together. I'm sure whatever choice you make will suit you best.\n\nGo examine the horses and return to me when you have made your choice.", objectives = "Inspect the riding horses to choose your first mount." }
WordHunterWoW_QuestEN[99411] = { title = "Kyle's Gone Missing!", description = "Help, {name}! My prized puppy, Kyle, has run away! I just know he's running around Bloodhoof Village, lost and hungry.\n\nWill you find him and feed him? Once he eats he will settle down and come home.\n\nTo feed him you will need to find food. His favorite meal is tender strider meat. Just venture east and you should find plenty of striders. Hunt one down and take its succulent meat to Kyle. When you see Kyle in town, put the meat down and he is sure to come to you.", objectives = "Ahab Wheathoof at Bloodhoof Village in Mulgore wants you to feed his prized puppy, Kyle the Frenzied.\n\nFeed Kyle Tender Strider Meat and return to Ahab Wheathoof.", completion = "Fantastic work, {name}! Kyle came home as soon as he ate and went straight to bed. Thank you for your help." }
WordHunterWoW_QuestEN[99435] = { title = "The Great Masquerade", description = "Windsor has already set off to confront Lady Prestor in Stormwind Keep, {class}. He spoke highly of your bravery. I suggest you hurry to his aid!\n\nHe is now certain that Prestor is Onyxia: Brood of Deathwing, twin to the tyrant of the Spire, Nefarian.\n\nAccording to him, even the Highlord is controlled by her trickery! The Marshal intends to break the spell and free all of Stormwind from the dark shadow of these fiends.\n\nFind him and ensure the deed is done!", objectives = "Follow Reginald Windsor through Stormwind. Protect him from harm!\n\nSpeak to Squire Rowe if you need to contact Reginald Windsor again." }
WordHunterWoW_QuestEN[99670] = { title = "Return to Jereman", description = "Jereman is fortunate to be alive. It sounds like she fled from the lodge in quite the hurry, no doubt thrilled to be freed from her predicament. \n\nShe will wish to speak with you. Go, find her.", objectives = "Return to Jereman at the Cradle of Tranquility." }
